def shell(title,body,depth=0,active='home'):
 p='../' if depth else ''
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Keith Young's computer science portfolio: coursework, projects, and professional goals at CSUMB."><title>{esc(title)} | Keith Young</title><link rel="stylesheet" href="{p}assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="{p}index.html"><span class="monogram">KY</span><span>Keith Young<small>Computer Science Portfolio</small></span></a><nav aria-label="Main navigation"><a {'aria-current="page"' if active=='home' else ''} href="{p}index.html">Home</a><a {'aria-current="page"' if active=='academic' else ''} href="{p}academic.html">Academic Portfolio</a><a {'aria-current="page"' if active=='projects' else ''} href="{p}projects.html">Projects</a></nav></header>{body}<footer><span>Keith Young · Computer Science, B.S. · Expected graduation: Summer 2028</span><span>Personal student portfolio · California State University Monterey Bay</span></footer><script src="{p}assets/site.js" defer></script></body></html>'''
home='''<main id="main"><section class="hero"><div><p class="eyebrow">KEITH YOUNG / COMPUTER SCIENCE</p><h1>Connecting technology<br>to practical solutions<span>.</span></h1><p class="lead">Building the knowledge to design reliable systems, improve processes, and turn ideas into useful tools.</p><div class="actions"><a class="button" href="academic.html">Explore my coursework <span aria-hidden="true">↗</span></a><a class="textlink" href="#about">About me ↓</a></div></div><aside class="hero-card"><p class="eyebrow">MY ACADEMIC PATH</p><img src="assets/csumb-logo.jpg" alt="Cal State Monterey Bay" width="300"><div class="card-rule"></div><h2>Computer Science, B.S.</h2><p>Online degree-completion program</p><dl><div><dt>Started</dt><dd>Fall 2026</dd></div><div><dt>Expected graduation</dt><dd>Summer 2028</dd></div></dl><a class="textlink" href="academic.html">View my learning plan →</a></aside></section><section class="about section" id="about"><div><p class="eyebrow">ABOUT ME</p><h2>A practical mindset.<br>A growing technical foundation.</h2></div><div><p>I'm Keith Young, a Computer Science student at California State University Monterey Bay. My interests sit at the intersection of technology, operations, and problem solving.</p><p>Through my coursework, I'm building skills in software development, networking, databases, and systems. My goal is to combine technical understanding with careful planning and clear communication to help teams prevent problems and deliver useful solutions.</p><p>This portfolio documents my academic work and will grow into a collection of projects that demonstrate how I apply what I learn.</p></div></section><section class="section program"><p class="eyebrow">THE PROGRAM</p><h2>Learning to build with purpose.</h2><p class="section-intro">CSUMB's online Computer Science program combines theoretical foundations, hands-on learning, collaborative work, and a culminating capstone. My learning goals across the planned coursework are:</p><div class="three-grid"><article><span class="number">01</span><h3>Design & develop</h3><p>Build a foundation in programming, software design, databases, and algorithmic problem solving.</p></article><article><span class="number">02</span><h3>Understand systems</h3><p>Study how operating systems, networks, and security support dependable computing.</p></article><article><span class="number">03</span><h3>Communicate & contribute</h3><p>Strengthen research, teamwork, ethical reasoning, and awareness of technology's social impact.</p></article></div><a class="textlink" href="https://csumb.edu/academics/programs-degrees/computer-science-online/">Explore the CSUMB program ↗</a></section><section class="section goals"><p class="eyebrow">WHAT I'M WORKING TOWARD</p><h2>From academic foundations to professional impact.</h2><div class="three-grid"><article><h3>Build reliable solutions</h3><p>Develop the skills to create maintainable software and well-planned systems.</p></article><article><h3>Connect teams and technology</h3><p>Translate technical concepts into clear decisions, documentation, and coordinated work.</p></article><article><h3>Keep learning through practice</h3><p>Use course projects and independent exploration to deepen my technical knowledge.</p></article></div></section></main>'''
home = home.replace('</main>', "<section class=\"section\" id=\"contact\"><p class=\"eyebrow\">GET IN TOUCH</p><h2>Let’s connect.</h2><p class=\"section-intro\">Reach out about projects, collaboration, or professional opportunities.</p><div class=\"three-grid\"><article><h3>Personal email</h3><a class=\"textlink\" href=\"mailto:permarack@gmail.com\">permarack@gmail.com</a></article><article><h3>University email</h3><a class=\"textlink\" href=\"mailto:keyoung@csumb.edu.com\">keyoung@csumb.edu.com</a></article><article><h3>LinkedIn</h3><a class=\"textlink\" href=\"https://www.linkedin.com/in/keith-young-811b49397/\">Connect with Keith Young ↗</a></article></div><!-- Future personal website: <a class=\"textlink\" href=\"https://permarack.com\">permarack.com ↗</a> --></section>" + '</main>')
(ROOT/'index.html').write_text(shell('Home',home))
terms=list(dict.fromkeys(x[2] for x in data))
academic='''<main id="main"><section class="page-heading"><p class="eyebrow">INDIVIDUAL LEARNING PLAN</p><h1>Academic portfolio<span>.</span></h1><p class="lead">A course-by-course record of my journey through CSUMB's Computer Science program.</p><p>Planned coursework · Fall 2026–Spring 2028</p></section><div class="filterbar"><label for="course-search">Find a course</label><input id="course-search" type="search" placeholder="Search by course number or title"><p id="search-status" role="status" aria-live="polite"></p></div>'''
for term in terms:
 academic+=f'<section class="term section"><div class="term-heading"><h2>{term}</h2><span>{sum(x[2]==term for x in data)} courses</span></div><div class="course-grid">'
 for code,title,t,session,summary in data:
  if t!=term:continue
  academic+=f'<a class="course-card" href="courses/cst-{code.lower()}.html" data-search="{esc(code+" "+title)}"><div class="course-meta"><strong>CST {code}</strong><span>Term {session}</span></div><h3>{esc(title)}</h3><p>{esc(summary)}</p><span class="card-bottom">View course <span aria-hidden="true">↗</span></span></a>'
 academic+='</div></section>'
academic+='</main>'
(ROOT/'academic.html').write_text(shell('Academic Portfolio',academic,active='academic'))
for i,(code,title,term,session,summary) in enumerate(data):
 links=''.join(f'<a {"aria-current=\"page\"" if c==code else ""} href="cst-{c.lower()}.html"><span>CST {c}</span> {esc(t)}</a>' for c,t,*_ in data)
 body=f'<main id="main" class="course-layout"><aside class="course-sidebar"><a class="textlink" href="../academic.html">← All coursework</a><details open><summary>Course navigation</summary><nav aria-label="Courses">{links}</nav></details></aside><article class="course-content"><p class="eyebrow">{term.upper()} / TERM {session}</p><h1><span class="course-code">CST {code}</span>{esc(title)}<span>.</span></h1><section class="content-section"><h2>Course description</h2><p>{esc(summary)}</p><p class="source-note">Provisional topic summary. Official catalog description to be added after verification.</p><a class="textlink" href="https://catalog.csumb.edu/">CSUMB course catalog ↗</a></section>'
 if code=='349':
  body+='<section class="content-section"><p class="eyebrow">REQUIRED COURSE ARTIFACT</p><h2>Industry Expert Interview Report</h2><div class="placeholder"><span class="badge">To be added</span><h3>A conversation with an industry professional</h3><p>The interview report will be added here with key insights, career takeaways, and a downloadable copy.</p></div></section>'
 body+='<section class="content-section"><h2>Final project</h2><div class="placeholder"><span class="badge">'+('Capstone ahead' if code=='499' else 'To be added')+'</span><h3>'+('A culmination of my learning' if code=='499' else 'Project showcase')+'</h3><p>'+('This page will document the capstone problem, solution, implementation, and results.' if code=='499' else 'Completed work will appear here with a project overview, my contribution, and links to the final deliverable or source code.')+'</p></div></section><section class="content-section"><h2>Skills & reflection</h2><p class="muted">After completing the course, I’ll document what I learned, how I applied it, and how it connects to my professional goals.</p></section><div class="course-pagination">'
 if i:body+=f'<a href="cst-{data[i-1][0].lower()}.html">← CST {data[i-1][0]}</a>'
 body+='<a href="../academic.html">All courses</a>'
 if i+1<len(data):body+=f'<a href="cst-{data[i+1][0].lower()}.html">CST {data[i+1][0]} →</a>'
 body+='</div></article></main>'
 (ROOT/f'courses/cst-{code.lower()}.html').write_text(shell(f'CST {code} — {title}',body,1,'academic'))
(ROOT/'projects.html').write_text(shell('Projects','<main id="main"><section class="page-heading"><p class="eyebrow">APPLIED LEARNING / INDEPENDENT PROJECT</p><h1>Projects<span>.</span></h1><p class="lead">Exploring practical systems through experimentation, troubleshooting, and documented decisions.</p></section><section class="section"><p class="eyebrow">FEATURED PROJECT</p><h2>Gaming today. Local AI next.</h2><p class="lead">A Proxmox homelab project exploring how one GPU-backed environment can support Steam/Proton gaming and, eventually, local AI workloads.</p><span class="badge">Ongoing · Gaming foundation validated · AI planned</span><div class="three-grid"><article><span class="number">PLATFORM</span><h3>Proxmox + Ubuntu LXC</h3><p>An unprivileged Ubuntu container with 16 CPU cores, 48 GiB of memory, and a 120 GB system disk.</p></article><article><span class="number">ACCELERATION</span><h3>Intel Arc Pro B50</h3><p>Host-managed GPU access for rendering, physical display output, and audio. Local AI acceleration is a future phase.</p></article><article><span class="number">EXPERIENCE</span><h3>Steam + Proton</h3><p>A local desktop gaming experience supported by directly mounted game storage and dynamically discovered input devices.</p></article></div></section><section class="section about"><div><p class="eyebrow">THE PROBLEM</p><h2>Make shared hardware useful and dependable.</h2></div><div><p>I wanted a single compute environment that could prioritize gaming while I was using it and perform local AI work when those resources were idle. The design also needed to fit alongside existing homelab services and support ongoing maintenance.</p><p>The initial challenge was establishing a dependable gaming foundation: graphics, audio, game storage, and physical input all had to work together before introducing AI workloads.</p></div></section><section class="section"><p class="eyebrow">MY CONTRIBUTION</p><h2>Design, implementation, and troubleshooting.</h2><div class="three-grid"><article><span class="number">01</span><h3>Evaluate architectures</h3><p>I tested a Bazzite-based virtual machine, rebuilt with Ubuntu, and investigated a host crash triggered by GPU passthrough. PCI BAR allocation failures helped guide the move to an LXC environment using the host GPU driver.</p></article><article><span class="number">02</span><h3>Integrate the gaming stack</h3><p>I configured GPU and audio access, a physical desktop, Steam/Proton, and a local game-library bind mount. This reduced the network-filesystem complexity encountered in the earlier design.</p></article><article><span class="number">03</span><h3>Make input maintainable</h3><p>I worked through device permissions, udev classification, and Steam Input. Dynamic input discovery replaced mappings tied to changing event numbers, and a refresh helper supports recovery after reconnects.</p></article></div></section><section class="section"><p class="eyebrow">ARCHITECTURE</p><h2>A host-managed GPU, a containerized workload.</h2><div class="three-grid"><article><h3>Proxmox host</h3><p>Owns hardware drivers and device discovery. Provides GPU, audio, and input interfaces to the gaming container.</p></article><article><h3>Ubuntu gaming container</h3><p>Runs the desktop, Steam, and Proton, with a directly mounted local game library. Steam Input uses virtual-controller support.</p></article><article><h3>Planned AI layer</h3><p>Local inference and orchestration will use the available compute resources after monitoring establishes a reliable baseline.</p></article></div></section><section class="section about"><div><p class="eyebrow">RESULTS SO FAR</p><h2>A working gaming foundation.</h2></div><div><ul><li>Validated GPU rendering, physical display output, and audio inside the Ubuntu LXC.</li><li>Launched representative games with Steam/Proton and validated local game storage.</li><li>Validated wired and Bluetooth input workflows and Steam virtual-controller support.</li><li>Validated an 8BitDo Ultimate 2 controller in Steam after refreshing input metadata.</li><li>Created runbooks and helper workflows for adding input devices and recovering session input.</li></ul><p class="source-note">Project documentation records these milestones in September 2026. Controller endurance testing and recovery-workflow refinement remain ongoing.</p></div></section><section class="section"><p class="eyebrow">LESSONS LEARNED</p><h2>Diagnose the boundary, then simplify the design.</h2><div class="three-grid"><article><h3>Use evidence to change direction</h3><p>Driver logs and stability tests were more useful than assuming full VM passthrough was the best fit. Changing the architecture helped establish a usable baseline.</p></article><article><h3>Separate discovery from access</h3><p>A device appearing in the container did not guarantee that the desktop or Steam classified it correctly. Permissions, metadata, and application state each required validation.</p></article><article><h3>Document repeatable operations</h3><p>Stable device identification and written runbooks make future additions easier to diagnose and maintain than one-off event-node mappings.</p></article></div></section><section class="section"><p class="eyebrow">NEXT PHASES</p><h2>Measure first. Add AI with a baseline.</h2><ol><li><strong>Monitoring:</strong> capture host/container CPU, memory, storage, network, GPU utilization, and driver health.</li><li><strong>Local inference:</strong> select a compatible runtime and benchmark models, resource use, and response latency.</li><li><strong>Orchestration:</strong> integrate Hermes with local/cloud routing and an approval workflow for infrastructure changes.</li><li><strong>Resource arbitration:</strong> have AI workloads yield when games launch, queue deferred work, and recover after gaming ends.</li><li><strong>Optimization:</strong> evaluate NPU use, CPU tuning, and model sizing using measured results.</li></ol><p class="source-note">These are planned capabilities; automated gaming/AI handoff is not yet implemented.</p></section><section class="section"><p class="eyebrow">SKILLS IN PRACTICE</p><p>Linux administration · Virtualization · Hardware integration · Root-cause analysis · Device permissions · Storage configuration · System documentation · Technical planning</p><a class="button" href="academic.html">Explore related coursework →</a></section></main>',active='projects'))

